def eval_task(self, agent_responses=None):
    metadata = {'correct_matter': False, "draft_found": False, "filing_found": False, "draft_content_ok": False, "slack_posted": False, "slack_content_ok": False, "keywords_found": [], "message": ""}
    try:
        # --- Draft / filing ---
        doc_text = ""
        for d in self.legal.get_drafts():
            c = (d.get("content") or "")
            if len(c.strip()) > 0:
                metadata["draft_found"] = True
            doc_text += " " + c
        for f in (self.legal.get_filings() + self.legal.get_prepared_filings()):
            c = (f.get("content") or "")
            if len(c.strip()) > 0:
                metadata["filing_found"] = True
            doc_text += " " + c

        doc_lower = self._normalize_text(doc_text.lower())
        draft_hits = sum(1 for p in DRAFT_REQUIRED_PHRASES if p in doc_lower)
        metadata["draft_content_ok"] = draft_hits >= DRAFT_MIN_PHRASES

        # --- Slack #ramirez-labor ---
        slack_text = ""
        _msg_count = 0
        try:
            for msg in channel_feed(token=self.slack_token, channel="ramirez-labor"):
                txt = (msg.get("text") or "").strip()
                if len(txt) > 20:
                    _msg_count += 1
                    slack_text += " " + txt
        except Exception:
            pass

        metadata["slack_posted"] = _msg_count >= 2

        slack_lower = self._normalize_text(slack_text.lower())
        slack_hits = sum(1 for p in SLACK_REQUIRED_PHRASES if p in slack_lower)
        metadata["slack_content_ok"] = slack_hits >= SLACK_MIN_PHRASES

        # --- Keywords (combined) ---
        combined_lower = self._normalize_text((doc_text + " " + slack_text).lower())
        for kw in TASK_KEYWORDS:
            if kw in combined_lower:
                metadata["keywords_found"].append(kw)

        # --- AND logic ---

        # Check drafts/filings have correct matter_id
        for _d in self.legal.get_drafts():
            if (_d.get('content') or '').strip() and _d.get('matter_id') == 'M-2024-643':
                metadata['correct_matter'] = True
        for _f in (self.legal.get_filings() + self.legal.get_prepared_filings()):
            if (_f.get('content') or '').strip() and _f.get('matter_id') == 'M-2024-643':
                metadata['correct_matter'] = True

        ok = (metadata["draft_found"] and metadata["draft_content_ok"]
              and metadata["slack_posted"]
              and metadata["slack_content_ok"]
              and len(metadata["keywords_found"]) >= 5
              and metadata['correct_matter'])

        parts = []
        if not metadata["draft_found"]:
            parts.append("no draft saved")
        if not metadata["filing_found"]:
            parts.append("no filing saved")
        if not metadata["draft_content_ok"]:
            parts.append(f"draft missing vault data ({draft_hits}/{DRAFT_MIN_PHRASES})")
        if not metadata["slack_posted"]:
            parts.append("no Slack post in #ramirez-labor")
        if not metadata["slack_content_ok"]:
            parts.append(f"Slack missing content ({slack_hits}/{SLACK_MIN_PHRASES})")
        if len(metadata["keywords_found"]) < 5:
            parts.append(f"keywords {len(metadata['keywords_found'])}/5")
        metadata["message"] = "Task complete" if ok else f"Incomplete: {'; '.join(parts)}"
        return ok, metadata
    except Exception as e:
        metadata["message"] = f"Error: {e}"
        return False, metadata
